"""Longest Common Subsequence — classic 2D DP rolled onto one row.

Matching characters extend the diagonal answer; otherwise the best of dropping
one character from either string wins.

Time: O(n*m)   Space: O(min(n, m))
"""


class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        if len(text2) > len(text1):
            text1, text2 = text2, text1
        previous = [0] * (len(text2) + 1)
        for a in text1:
            current = [0]
            for j, b in enumerate(text2):
                if a == b:
                    current.append(previous[j] + 1)
                else:
                    current.append(max(previous[j + 1], current[j]))
            previous = current
        return previous[-1]
